function cloneWith(base, overrides) {
  return {
    ...base,
    ...overrides,
    common: { ...base.common, ...overrides.common },
    nav: { ...base.nav, ...overrides.nav },
    home: { ...base.home, ...overrides.home },
    pages: Object.fromEntries(Object.keys(base.pages).map((key) => [key, { ...base.pages[key], ...(overrides.pages?.[key] || {}) }])),
    data: { ...base.data, ...overrides.data },
    footer: { ...base.footer, ...overrides.footer },
  };
}

